<?php declare(strict_types=1);use FastWebsite\Core\View;$value=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($itemId);?>
<section class="admin-page-heading"><div><p class="eyebrow"><?=$editing?'Innovation revision':'New innovation'?></p><h1><?=$editing?'Edit innovation':'Create innovation'?></h1><p>Published innovations remain editable by authorized publishers.</p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/innovations">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$error):?><li><?=View::escape($error)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" method="post" enctype="multipart/form-data" action="<?=View::escape($baseUrl)?>admin/innovations<?=$editing?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><input type="hidden" name="MAX_FILE_SIZE" value="20971520"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label for="name">Innovation name *</label><input id="name" name="name" required maxlength="255" value="<?=View::escape($value('name'))?>"></div><div class="form-field span-2"><label for="slug">Public URL</label><input id="slug" name="slug" maxlength="280" value="<?=View::escape($value('slug'))?>"></div><div class="form-field"><label for="lead_department_id">Lead department *</label><select id="lead_department_id" name="lead_department_id" required><?php foreach($departments as$d):?><option value="<?=(int)$d['id']?>"<?=$value('lead_department_id')===(string)$d['id']?' selected':''?>><?=View::escape($d['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="project_id">Linked project</label><select id="project_id" name="project_id"><option value="">No project</option><?php foreach($projects as$p):?><option value="<?=(int)$p['id']?>"<?=$value('project_id')===(string)$p['id']?' selected':''?>><?=View::escape($p['title'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="innovation_type">Type</label><select id="innovation_type" name="innovation_type"><?php foreach(['prototype','patent','software','device','process','product','service','other']as$type):?><option value="<?=$type?>"<?=$value('innovation_type')===$type?' selected':''?>><?=ucfirst($type)?></option><?php endforeach;?></select></div><div class="form-field"><label for="development_stage">Development stage</label><select id="development_stage" name="development_stage"><option value="">Not set</option><?php foreach(['concept','research','prototype','pilot','validated','commercialised','scaled','other']as$stage):?><option value="<?=$stage?>"<?=$value('development_stage')===$stage?' selected':''?>><?=ucfirst($stage)?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="intellectual_property_status">Intellectual property status</label><input id="intellectual_property_status" name="intellectual_property_status" maxlength="200" value="<?=View::escape($value('intellectual_property_status'))?>"></div><div class="form-field span-2"><label for="external_url">External URL</label><input id="external_url" name="external_url" type="url" maxlength="500" value="<?=View::escape($value('external_url'))?>"></div><div class="form-field span-2"><label for="description">Description *</label><textarea id="description" name="description" rows="9"><?=View::escape($value('description'))?></textarea></div></div></section><section class="form-section"><h2>Image</h2><div class="form-grid"><div class="form-field span-2"><label for="hero_media_id">Existing image</label><select id="hero_media_id" name="hero_media_id" data-media-upload="<?=View::escape($baseUrl)?>admin/media"><option value="">No image</option><?php foreach($images as$image):?><option value="<?=(int)$image['id']?>"<?=$value('hero_media_id')===(string)$image['id']?' selected':''?>><?=View::escape($image['original_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="hero_image">Upload image</label><input id="hero_image" name="hero_image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="form-field"><label for="hero_alt_text">Image description</label><input id="hero_alt_text" name="hero_alt_text" maxlength="255"></div></div></section><div class="form-actions"><button class="button <?=$canPublish?'button-secondary':'button-primary'?>" name="submit_action" value="save">Save</button><?php if($canPublish):?><button class="button button-primary" name="submit_action" value="publish">Save and publish</button><?php endif;?></div></form>
